import csv
import sqlite3

cn = sqlite3.connect('db/satscores.db')
rows = cn.execute("SELECT cds, sname, dname, AvgScrMath FROM satscores WHERE dname IN ('Riverside Unified', 'Riverside County Office of Education')").fetchall()
sats = {r[0]:{'sname':r[1],'AvgScrMath':r[3]} for r in rows}
cn.close()

# Build district averages
dist_scores = {'Riverside Unified':[], 'Riverside County Office of Education':[]}
for s, m in sats.values():
    if m is not None:
        for row in rows:
            if row[0] == s and m == row[3]:
                dist_scores[row[2]].append(m)
                break

qualifying = [d for d,scores in dist_scores.items() if sum(scores)/len(scores) > 400]
print(f"Qualifying: {qualifying}")

with open('csv/frpm.csv') as f:
    frpm = list(csv.DictReader(f))

result = []
for f in frpm:
    dname = f.get('District Name','')
    if dname not in qualifying: continue
    result.append((f.get('School Name',''), f.get('Charter Funding Type','') or 'N/A'))

print(f"Schools from frpm: {len(result)}")
for s, ft in result:
    print(f"{s}, {ft}")

